// javelin-tracker-frontend/src/components/layout/Header.jsx
import React, { useState, useEffect, useRef } from 'react';
import WifiPanel from './WifiPanel';
import { getWifiStatus } from '../../services/api';

const Header = () => {
  const [showWifiPanel, setShowWifiPanel] = useState(false);
  const [wifiStatus, setWifiStatus] = useState({ isConnected: false, ssid: null });
  const headerRef = useRef(null);

  const checkWifiStatus = async () => {
    const status = await getWifiStatus();
    console.log("Header received status:", status); // Debug log
    setWifiStatus({
      isConnected: status.isConnected,
      ssid: status.ssid || null
    });
  };

  useEffect(() => {
    checkWifiStatus();
    const interval = setInterval(checkWifiStatus, 10000); // Check every 10 seconds
    return () => clearInterval(interval);
  }, []);

  const handleWifiClick = () => {
    setShowWifiPanel(prev => !prev);
  };

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (headerRef.current && !headerRef.current.contains(event.target)) {
        setShowWifiPanel(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const containerClasses = wifiStatus.isConnected
    ? 'bg-primary border-purple-400'
    : 'bg-surface border-border-color hover:bg-border-color hover:border-gray-500';

  const iconClasses = wifiStatus.isConnected
    ? 'text-white'
    : 'text-on-surface-secondary group-hover:text-on-surface';

  return (
    <header ref={headerRef} className="bg-surface p-4 flex justify-between items-center h-16 border-b border-border-color flex-shrink-0">
      <div className="flex items-center space-x-3">
        <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-primary" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={1.5}>
          <path strokeLinecap="round" strokeLinejoin="round" d="M13 10V3L4 14h7v7l9-11h-7z" />
        </svg>
        <span className="text-xl font-semibold text-on-surface">Javelin Tracker</span>
      </div>

      <div className="relative">
        <div onClick={handleWifiClick} className={`group w-10 h-10 rounded-full flex items-center justify-center border cursor-pointer transition-colors duration-200 ${containerClasses}`}>
          <svg xmlns="http://www.w3.org/2000/svg" className={`h-6 w-6 transition-colors duration-200 ${iconClasses}`} fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
            <path strokeLinecap="round" strokeLinejoin="round" d="M8.625 15a4.125 4.125 0 016.75 0" />
            <path strokeLinecap="round" strokeLinejoin="round" d="M5.25 11.625a8.625 8.625 0 0113.5 0" />
            <path strokeLinecap="round" strokeLinejoin="round" d="M1.875 8.25a13.125 13.125 0 0120.25 0M12 18.75a.75.75 0 100-1.5.75.75 0 000 1.5z" />
          </svg>
        </div>
        {showWifiPanel && (
          <WifiPanel
            initialStatus={wifiStatus}
            onStatusChange={setWifiStatus}
            closePanel={() => setShowWifiPanel(false)}
          />
        )}
      </div>
    </header>
  );
};

export default Header;
